fn is_non_prime(n: u64) -> bool {
    // n is assumed to be at least 2
    if n == 2 {
        return false;
    }
    
    // Even numbers greater than 2 are composite
    if n % 2 == 0 {
        return true;
    }
    
    // Check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    let mut divisor = 3;
    while divisor <= limit {
        if n % divisor == 0 {
            return true;
        }
        divisor += 2;
    }
    
    false
}